  upgradeIcon(weapon: string) { return weapon === 'laser' ? '⚡' : weapon === 'missile' ? '🚀' : weapon === 'shield' ? '🛡️' : weapon === 'plasma' ? '☄️' : weapon === 'drone' ? '🛸' : weapon === 'rail' ? '💥' : weapon === 'flak' ? '💣' : weapon === 'tesla' ? '🌩️' : weapon === 'chem' ? '☢️' : weapon === 'health' ? '❤️' : weapon === 'ship' ? '🛰️' : '🧬'; }
