  private canPlasmaConvert(b: SpaceBug) { return b.hp > 0 && !b.ally && b.kind !== 'boss' && b.boss !== true; } private hasLiveHostiles() { for (const b of this.bugs) if (b.hp > 0 && !b.ally && Number.isFinite(b.x) && Number.isFinite(b.y)) return true; return false; } private convertedEnemyCount() { let count = 0; for (const b of this.bugs) if (b.ally && b.hp > 0) count++; return count; } private removeOldestConverted() { let index = -1; let oldest = Infinity; for (let i = 0; i < this.bugs.length; i++) { const b = this.bugs[i]; if (!b.ally || b.hp <= 0) continue; const order = b.conversionOrder ?? i; if (order < oldest) { oldest = order; index = i; } } if (index >= 0) this.killBug(index); } private nearestEnemyForAlly(ally: SpaceBug) { let best: SpaceBug | undefined; let distance = Infinity; for (const b of this.bugs) { if (b === ally || b.ally || b.hp <= 0) continue; const d = Math.hypot(b.x - ally.x, b.y - ally.y); if (d < distance) { distance = d; best = b; } } return best; } private nearestIncoming(x: number, y: number) { let best: SpaceBug | undefined; let distance = Infinity; for (const b of this.bugs) { if (b.ally || b.hp <= 0) continue; const d = Math.hypot(b.x - x, b.y - y); if (d < distance) { distance = d; best = b; } } return best; }
